/// The column table of a kernel and order, if it was exported
pub fn column_table(kernel: &str, order: i32) -> Option<&'static ColumnTable> {
    match (kernel, order) {
        ("a1", 0) => Some(&A1_D0),
        ("a3", 0) => Some(&A3_D0),
        ("a4", 0) => Some(&A4_D0),
        ("a5", 0) => Some(&A5_D0),
        ("a7", 0) => Some(&A7_D0),
        ("b5", 0) => Some(&B5_D0),
        ("b7", 0) => Some(&B7_D0),
        ("b9", 0) => Some(&B9_D0),
        ("b11", 0) => Some(&B11_D0),
        ("b13", 0) => Some(&B13_D0),
        _ => None,
    }
}
